import { useState } from 'react'
import { motion } from 'framer-motion'
import { History, Trash2, Edit2, Save, X, AlertCircle } from 'lucide-react'
import { useAppContext } from '../../context/AppContext'
import { Card } from '../UI/Card'
import { formatDateFull } from '../../utils/cycleCalculations'

export function HistoryView() {
  const { t, history, deleteHistoryItem, updateHistoryItem, isRTL } = useAppContext()
  const [editingId, setEditingId] = useState(null)
  const [editData, setEditData] = useState({})
  const [deleteConfirm, setDeleteConfirm] = useState(null)

  const handleEdit = (item) => {
    setEditingId(item.id)
    setEditData({
      cycleLength: item.cycleLength,
      periodDuration: item.periodDuration,
    })
  }

  const handleSave = (id) => {
    updateHistoryItem(id, editData)
    setEditingId(null)
  }

  const handleDelete = (id) => {
    if (deleteConfirm === id) {
      deleteHistoryItem(id)
      setDeleteConfirm(null)
    } else {
      setDeleteConfirm(id)
      setTimeout(() => setDeleteConfirm(null), 3000)
    }
  }

  return (
    <section id="history" className="section-padding py-12">
      <div className="max-w-4xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
          className="text-center mb-10"
        >
          <div className="inline-flex items-center justify-center w-14 h-14 mb-4 rounded-2xl bg-gradient-to-br from-primary-400 to-primary-600 shadow-lg">
            <History className="w-7 h-7 text-white" />
          </div>
          <h2 className="text-3xl sm:text-4xl font-bold mb-4">{t.history.title}</h2>
          <div className="w-16 h-1 bg-gradient-to-r from-primary-500 to-accent-500 rounded-full mx-auto" />
        </motion.div>

        {history.length === 0 ? (
          <Card className="p-12 text-center">
            <History className="w-16 h-16 text-[var(--color-text-muted)] mx-auto mb-4" />
            <p className="text-[var(--color-text-secondary)]">{t.history.noHistory}</p>
          </Card>
        ) : (
          <div className="space-y-4">
            {history.map((item, index) => (
              <motion.div
                key={item.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: index * 0.05 }}
              >
                <Card className="p-4 sm:p-6">
                  <div className="flex flex-col sm:flex-row sm:items-center gap-4">
                    <div className="flex-1 grid grid-cols-1 sm:grid-cols-3 gap-4">
                      <div>
                        <p className="text-xs text-[var(--color-text-muted)] mb-1">{t.history.date}</p>
                        <p className="font-medium">
                          {formatDateFull(item.lastPeriodDate, isRTL ? 'ar' : 'en')}
                        </p>
                      </div>
                      <div>
                        <p className="text-xs text-[var(--color-text-muted)] mb-1">{t.history.cycleLength}</p>
                        {editingId === item.id ? (
                          <input
                            type="number"
                            min="21"
                            max="40"
                            value={editData.cycleLength}
                            onChange={(e) => setEditData({ ...editData, cycleLength: e.target.value })}
                            className="w-20 input-field py-1 px-2 text-sm"
                          />
                        ) : (
                          <p className="font-medium">{item.cycleLength} {t.calculator.days}</p>
                        )}
                      </div>
                      <div>
                        <p className="text-xs text-[var(--color-text-muted)] mb-1">{t.history.periodDuration}</p>
                        {editingId === item.id ? (
                          <input
                            type="number"
                            min="2"
                            max="10"
                            value={editData.periodDuration}
                            onChange={(e) => setEditData({ ...editData, periodDuration: e.target.value })}
                            className="w-20 input-field py-1 px-2 text-sm"
                          />
                        ) : (
                          <p className="font-medium">{item.periodDuration} {t.calculator.days}</p>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      {editingId === item.id ? (
                        <>
                          <button onClick={() => handleSave(item.id)} className="p-2 rounded-lg bg-primary-100 text-primary-600 hover:bg-primary-200 transition-colors">
                            <Save className="w-4 h-4" />
                          </button>
                          <button onClick={() => setEditingId(null)} className="p-2 rounded-lg bg-[var(--color-surface)] text-[var(--color-text-muted)] hover:bg-[var(--color-border)] transition-colors">
                            <X className="w-4 h-4" />
                          </button>
                        </>
                      ) : (
                        <>
                          <button onClick={() => handleEdit(item)} className="p-2 rounded-lg bg-[var(--color-surface)] text-[var(--color-text-muted)] hover:bg-primary-100 hover:text-primary-600 transition-colors">
                            <Edit2 className="w-4 h-4" />
                          </button>
                          <button onClick={() => handleDelete(item.id)} className={`p-2 rounded-lg transition-colors ${deleteConfirm === item.id ? 'bg-red-100 text-red-600' : 'bg-[var(--color-surface)] text-[var(--color-text-muted)] hover:bg-red-100 hover:text-red-600'}`}>
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </>
                      )}
                    </div>
                  </div>
                  {deleteConfirm === item.id && (
                    <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} className="mt-3 p-3 bg-red-50 dark:bg-red-900/20 rounded-lg flex items-center gap-2 text-sm text-red-600">
                      <AlertCircle className="w-4 h-4" />
                      {t.history.confirmDelete}
                    </motion.div>
                  )}
                </Card>
              </motion.div>
            ))}
          </div>
        )}
      </div>
    </section>
  )
}
