import { motion } from 'framer-motion'
import { Printer, Heart, Egg, Sprout, CalendarDays, Clock } from 'lucide-react'
import { useAppContext } from '../../context/AppContext'
import { Card } from '../UI/Card'
import { Button } from '../UI/Button'
import { formatDateFull, formatDateShort, formatDateRange } from '../../utils/cycleCalculations'

export function ExportView({ results }) {
  const { t, isRTL } = useAppContext()

  if (!results) return null

  const handlePrint = () => {
    window.print()
  }

  return (
    <section className="section-padding py-12 no-print">
      <div className="max-w-4xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
          className="text-center mb-10"
        >
          <h2 className="text-3xl sm:text-4xl font-bold mb-4">{t.export.title}</h2>
          <div className="w-16 h-1 bg-gradient-to-r from-primary-500 to-accent-500 rounded-full mx-auto" />
        </motion.div>

        <div className="flex flex-col sm:flex-row gap-4 mb-8 justify-center no-print">
          <Button variant="secondary" icon={Printer} onClick={handlePrint}>
            {t.export.print}
          </Button>
        </div>

        <div id="cycle-report" className="bg-white dark:bg-[var(--color-surface-elevated)] rounded-2xl p-8 shadow-lg">
          <div className="text-center mb-8 border-b border-gray-200 dark:border-gray-700 pb-6">
            <div className="inline-flex items-center justify-center w-16 h-16 mb-4 rounded-2xl bg-gradient-to-br from-primary-400 to-primary-600">
              <Heart className="w-8 h-8 text-white" />
            </div>
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-2">{t.export.reportTitle}</h1>
            <p className="text-gray-500 dark:text-gray-400">
              {t.export.generatedOn}: {formatDateFull(new Date(), isRTL ? 'ar' : 'en')}
            </p>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 mb-8">
            <div className="p-4 bg-red-50 dark:bg-red-900/20 rounded-xl">
              <div className="flex items-center gap-2 mb-2">
                <Heart className="w-5 h-5 text-red-500" />
                <span className="font-medium text-gray-900 dark:text-white">{t.results.nextPeriod}</span>
              </div>
              <p className="text-2xl font-bold text-red-600">{formatDateFull(results.nextPeriodStart, isRTL ? 'ar' : 'en')}</p>
            </div>
            <div className="p-4 bg-primary-50 dark:bg-primary-900/20 rounded-xl">
              <div className="flex items-center gap-2 mb-2">
                <Egg className="w-5 h-5 text-primary-500" />
                <span className="font-medium text-gray-900 dark:text-white">{t.results.ovulation}</span>
              </div>
              <p className="text-2xl font-bold text-primary-600">{formatDateFull(results.ovulationDate, isRTL ? 'ar' : 'en')}</p>
            </div>
            <div className="p-4 bg-emerald-50 dark:bg-emerald-900/20 rounded-xl">
              <div className="flex items-center gap-2 mb-2">
                <Sprout className="w-5 h-5 text-emerald-500" />
                <span className="font-medium text-gray-900 dark:text-white">{t.results.fertileWindow}</span>
              </div>
              <p className="text-2xl font-bold text-emerald-600">
                {formatDateRange(results.fertileStart, results.fertileEnd, isRTL ? 'ar' : 'en')}
              </p>
            </div>
            <div className="p-4 bg-violet-50 dark:bg-violet-900/20 rounded-xl">
              <div className="flex items-center gap-2 mb-2">
                <Clock className="w-5 h-5 text-violet-500" />
                <span className="font-medium text-gray-900 dark:text-white">{t.results.daysRemaining}</span>
              </div>
              <p className="text-2xl font-bold text-violet-600">{results.daysRemaining} {t.calculator.days}</p>
            </div>
          </div>

          <div className="mb-6">
            <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
              <CalendarDays className="w-5 h-5 text-primary-500" />
              {t.results.nextCycles}
            </h3>
            <div className="space-y-3">
              {results.nextCycles.map((cycle, index) => (
                <div key={index} className="flex items-center gap-4 p-4 bg-gray-50 dark:bg-gray-800/50 rounded-xl">
                  <div className="w-8 h-8 rounded-full bg-primary-100 dark:bg-primary-900/40 flex items-center justify-center text-primary-600 font-bold text-sm">
                    {index + 1}
                  </div>
                  <div>
                    <p className="font-medium text-gray-900 dark:text-white">
                      {formatDateRange(cycle.periodStart, cycle.periodEnd, isRTL ? 'ar' : 'en')}
                    </p>
                    <p className="text-sm text-gray-500 dark:text-gray-400">
                      {t.results.ovulation}: {formatDateShort(cycle.ovulation, isRTL ? 'ar' : 'en')}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="text-center text-sm text-gray-500 dark:text-gray-400 pt-6 border-t border-gray-200 dark:border-gray-700">
            {t.footer.disclaimer}
          </div>
        </div>
      </div>
    </section>
  )
}
