import { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { X, Trash2, AlertTriangle, Sun, Moon, Monitor, Globe } from 'lucide-react'
import { useAppContext } from '../../context/AppContext'
import { Button } from '../UI/Button'

export function SettingsModal() {
  const { t, theme, setTheme, language, setLanguage, showSettings, setShowSettings, clearAllHistory } = useAppContext()
  const [showClearConfirm, setShowClearConfirm] = useState(false)

  const handleClearData = () => {
    if (showClearConfirm) {
      clearAllHistory()
      setShowClearConfirm(false)
      setShowSettings(false)
    } else {
      setShowClearConfirm(true)
    }
  }

  const themes = [
    { id: 'light', label: t.settings.light, icon: Sun },
    { id: 'dark', label: t.settings.dark, icon: Moon },
    { id: 'system', label: t.settings.system, icon: Monitor },
  ]

  return (
    <AnimatePresence>
      {showSettings && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm"
          onClick={() => setShowSettings(false)}
        >
          <motion.div
            initial={{ opacity: 0, scale: 0.95, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: 20 }}
            onClick={(e) => e.stopPropagation()}
            className="bg-[var(--color-surface-elevated)] rounded-2xl shadow-2xl w-full max-w-md max-h-[90vh] overflow-y-auto"
          >
            <div className="sticky top-0 bg-[var(--color-surface-elevated)] border-b border-[var(--color-border)] p-4 sm:p-6 flex items-center justify-between rounded-t-2xl">
              <h2 className="text-xl font-bold">{t.settings.title}</h2>
              <button
                onClick={() => setShowSettings(false)}
                className="p-2 rounded-xl hover:bg-[var(--color-surface)] transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-4 sm:p-6 space-y-8">
              {/* Language */}
              <div>
                <h3 className="text-sm font-medium text-[var(--color-text-muted)] mb-3 flex items-center gap-2">
                  <Globe className="w-4 h-4" />
                  {t.settings.language}
                </h3>
                <div className="grid grid-cols-2 gap-3">
                  <button
                    onClick={() => setLanguage('en')}
                    className={`p-3 rounded-xl border-2 transition-all ${
                      language === 'en'
                        ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20'
                        : 'border-[var(--color-border)] hover:border-primary-200'
                    }`}
                  >
                    <span className="font-medium">English</span>
                  </button>
                  <button
                    onClick={() => setLanguage('ar')}
                    className={`p-3 rounded-xl border-2 transition-all ${
                      language === 'ar'
                        ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20'
                        : 'border-[var(--color-border)] hover:border-primary-200'
                    }`}
                  >
                    <span className="font-medium">العربية</span>
                  </button>
                </div>
              </div>

              {/* Theme */}
              <div>
                <h3 className="text-sm font-medium text-[var(--color-text-muted)] mb-3">{t.settings.theme}</h3>
                <div className="grid grid-cols-3 gap-3">
                  {themes.map((tItem) => (
                    <button
                      key={tItem.id}
                      onClick={() => setTheme(tItem.id)}
                      className={`p-3 rounded-xl border-2 transition-all flex flex-col items-center gap-2 ${
                        theme === tItem.id
                          ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20'
                          : 'border-[var(--color-border)] hover:border-primary-200'
                      }`}
                    >
                      <tItem.icon className="w-5 h-5" />
                      <span className="text-sm font-medium">{tItem.label}</span>
                    </button>
                  ))}
                </div>
              </div>

              {/* Data Management */}
              <div>
                <h3 className="text-sm font-medium text-[var(--color-text-muted)] mb-3 flex items-center gap-2">
                  <Trash2 className="w-4 h-4" />
                  {t.settings.data}
                </h3>
                <div className="p-4 rounded-xl bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800">
                  {showClearConfirm ? (
                    <div className="space-y-3">
                      <div className="flex items-start gap-2 text-red-600 dark:text-red-400">
                        <AlertTriangle className="w-5 h-5 shrink-0" />
                        <p className="text-sm">{t.settings.clearConfirm}</p>
                      </div>
                      <div className="flex gap-2">
                        <Button variant="danger" size="sm" onClick={handleClearData} className="flex-1">
                          {t.settings.clearData}
                        </Button>
                        <Button variant="secondary" size="sm" onClick={() => setShowClearConfirm(false)} className="flex-1">
                          {t.history.cancel}
                        </Button>
                      </div>
                    </div>
                  ) : (
                    <Button variant="danger" size="sm" onClick={handleClearData} className="w-full">
                      {t.settings.clearData}
                    </Button>
                  )}
                </div>
              </div>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  )
}
