import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Menu, X, Heart, Sun, Moon, Monitor, Settings } from 'lucide-react'
import { useAppContext } from '../../context/AppContext'

export function Navigation() {
  const { t, theme, setTheme, language, setLanguage, isRTL, setShowSettings } = useAppContext()
  const [isScrolled, setIsScrolled] = useState(false)
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false)

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 20)
    window.addEventListener('scroll', handleScroll)
    return () => window.removeEventListener('scroll', handleScroll)
  }, [])

  const navItems = [
    { id: 'calculator', label: t.nav.calculator },
    { id: 'calendar', label: t.nav.calendar },
    { id: 'history', label: t.nav.history },
  ]

  const scrollToSection = (id) => {
    const element = document.getElementById(id)
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' })
      setIsMobileMenuOpen(false)
    }
  }

  const getThemeIcon = () => {
    if (theme === 'dark') return <Moon className="w-5 h-5" />
    if (theme === 'light') return <Sun className="w-5 h-5" />
    return <Monitor className="w-5 h-5" />
  }

  return (
    <>
      <motion.nav
        initial={{ y: -100 }}
        animate={{ y: 0 }}
        transition={{ duration: 0.5 }}
        className={`fixed top-0 left-0 right-0 z-[100] transition-all duration-300 ${
          isScrolled 
            ? 'glass-strong shadow-lg' 
            : 'bg-white/80 dark:bg-[#0f172a]/80 backdrop-blur-md'
        }`}
      >
        <div className="max-w-7xl mx-auto section-padding">
          <div className="flex items-center justify-between h-16 sm:h-20">
            {/* Logo */}
            <a href="/" className="flex items-center gap-2 z-10">
              <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-primary-400 to-primary-600 flex items-center justify-center">
                <Heart className="w-5 h-5 text-white" />
              </div>
              <span className="font-bold text-lg hidden sm:block">{t.appName}</span>
            </a>

            {/* Desktop Navigation */}
            <div className="hidden md:flex items-center gap-1 z-10">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => scrollToSection(item.id)}
                  className="px-4 py-2 rounded-xl text-sm font-medium text-[var(--color-text-secondary)] hover:text-[var(--color-text)] hover:bg-[var(--color-surface)] transition-all"
                >
                  {item.label}
                </button>
              ))}
            </div>

            {/* Actions */}
            <div className="flex items-center gap-2 z-10">
              <button
                onClick={() => setLanguage(language === 'en' ? 'ar' : 'en')}
                className="p-2.5 rounded-xl hover:bg-[var(--color-surface)] transition-colors text-sm font-medium"
                aria-label="Toggle language"
              >
                {language === 'en' ? 'AR' : 'EN'}
              </button>
              <button
                onClick={() => setTheme(theme === 'light' ? 'dark' : theme === 'dark' ? 'system' : 'light')}
                className="p-2.5 rounded-xl hover:bg-[var(--color-surface)] transition-colors"
                aria-label="Toggle theme"
              >
                {getThemeIcon()}
              </button>
              <button
                onClick={() => setShowSettings(true)}
                className="p-2.5 rounded-xl hover:bg-[var(--color-surface)] transition-colors hidden sm:flex"
                aria-label="Settings"
              >
                <Settings className="w-5 h-5" />
              </button>
              <button
                onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                className="p-2.5 rounded-xl hover:bg-[var(--color-surface)] transition-colors md:hidden"
                aria-label="Menu"
              >
                {isMobileMenuOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}
              </button>
            </div>
          </div>
        </div>
      </motion.nav>

      {/* Mobile Menu */}
      <AnimatePresence>
        {isMobileMenuOpen && (
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            className="fixed inset-0 z-[99] pt-20 glass-strong md:hidden"
          >
            <div className="section-padding py-6 space-y-2">
              {navItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => scrollToSection(item.id)}
                  className="w-full text-start px-4 py-3 rounded-xl text-lg font-medium hover:bg-[var(--color-surface)] transition-colors"
                >
                  {item.label}
                </button>
              ))}
              <button
                onClick={() => {
                  setShowSettings(true)
                  setIsMobileMenuOpen(false)
                }}
                className="w-full text-start px-4 py-3 rounded-xl text-lg font-medium hover:bg-[var(--color-surface)] transition-colors flex items-center gap-3"
              >
                <Settings className="w-5 h-5" />
                {t.nav.settings}
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  )
}
