import { motion } from 'framer-motion'
import { Heart, Egg, Sprout, CalendarDays, Clock, ChevronRight, ChevronLeft } from 'lucide-react'
import { useAppContext } from '../../context/AppContext'
import { Card } from '../UI/Card'
import { formatDateShort, formatDateRange } from '../../utils/cycleCalculations'

export function ResultCards({ results }) {
  const { t, isRTL } = useAppContext()

  const cards = [
    {
      icon: Heart,
      title: t.results.nextPeriod,
      value: formatDateShort(results.nextPeriodStart, isRTL ? 'ar' : 'en'),
      color: 'from-red-400 to-red-600',
      textColor: 'text-red-600',
    },
    {
      icon: Egg,
      title: t.results.ovulation,
      value: formatDateShort(results.ovulationDate, isRTL ? 'ar' : 'en'),
      color: 'from-primary-400 to-primary-600',
      textColor: 'text-primary-600',
    },
    {
      icon: Sprout,
      title: t.results.fertileWindow,
      value: formatDateRange(results.fertileStart, results.fertileEnd, isRTL ? 'ar' : 'en'),
      color: 'from-emerald-400 to-emerald-600',
      textColor: 'text-emerald-600',
    },
    {
      icon: Clock,
      title: t.results.daysRemaining,
      value: `${results.daysRemaining} ${t.calculator.days}`,
      color: 'from-violet-400 to-violet-600',
      textColor: 'text-violet-600',
    },
  ]

  return (
    <section id="results" className="section-padding py-12">
      <div className="max-w-6xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
          className="text-center mb-10"
        >
          <h2 className="text-3xl sm:text-4xl font-bold mb-4">{t.results.title}</h2>
          <div className="w-16 h-1 bg-gradient-to-r from-primary-500 to-accent-500 rounded-full mx-auto" />
        </motion.div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-10">
          {cards.map((card, index) => (
            <motion.div
              key={card.title}
              initial={{ opacity: 0, y: 30 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.4, delay: index * 0.1 }}
            >
              <Card className="h-full">
                <div className={`w-12 h-12 rounded-xl bg-gradient-to-br ${card.color} flex items-center justify-center mb-4`}>
                  <card.icon className="w-6 h-6 text-white" />
                </div>
                <p className="text-sm text-[var(--color-text-muted)] mb-1">{card.title}</p>
                <p className={`text-lg font-bold ${card.textColor}`}>{card.value}</p>
              </Card>
            </motion.div>
          ))}
        </div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.4 }}
        >
          <Card>
            <div className="flex items-center gap-3 mb-6">
              <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-primary-400 to-primary-600 flex items-center justify-center">
                <CalendarDays className="w-5 h-5 text-white" />
              </div>
              <h3 className="text-lg font-bold">{t.results.nextCycles}</h3>
            </div>
            <div className="space-y-3">
              {results.nextCycles.map((cycle, index) => (
                <motion.div
                  key={index}
                  initial={{ opacity: 0, x: isRTL ? 20 : -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: 0.5 + index * 0.1 }}
                  className="flex items-center gap-4 p-4 rounded-xl bg-[var(--color-surface)] border border-[var(--color-border)]"
                >
                  <div className="w-10 h-10 rounded-full bg-gradient-to-br from-primary-400 to-primary-600 flex items-center justify-center text-white font-bold text-sm">
                    {index + 1}
                  </div>
                  <div className="flex-1">
                    <p className="font-medium">
                      {formatDateRange(cycle.periodStart, cycle.periodEnd, isRTL ? 'ar' : 'en')}
                    </p>
                    <p className="text-sm text-[var(--color-text-muted)]">
                      {t.results.ovulation}: {formatDateShort(cycle.ovulation, isRTL ? 'ar' : 'en')}
                    </p>
                  </div>
                  {isRTL ? <ChevronLeft className="w-5 h-5 text-[var(--color-text-muted)]" /> : <ChevronRight className="w-5 h-5 text-[var(--color-text-muted)]" />}
                </motion.div>
              ))}
            </div>
          </Card>
        </motion.div>
      </div>
    </section>
  )
}
