import { useState } from 'react'
import { motion } from 'framer-motion'
import { CalendarIcon, RotateCcw, Calculator } from 'lucide-react'
import { useAppContext } from '../../context/AppContext'
import { Button } from '../UI/Button'
import { Card } from '../UI/Card'
import DatePicker from '../UI/DatePicker'

export function CalculatorForm({ onCalculate }) {
  const { t, isRTL } = useAppContext()
  const [lastPeriodDate, setLastPeriodDate] = useState('')
  const [cycleLength, setCycleLength] = useState(28)
  const [periodDuration, setPeriodDuration] = useState(5)
  const [errors, setErrors] = useState({})

  const validate = () => {
    const newErrors = {}
    if (!lastPeriodDate) newErrors.date = t.calculator.errors.dateRequired
    if (cycleLength < 21 || cycleLength > 40) newErrors.cycleLength = t.calculator.errors.cycleLength
    if (periodDuration < 2 || periodDuration > 10) newErrors.periodDuration = t.calculator.errors.periodDuration
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = (e) => {
    e.preventDefault()
    if (validate()) {
      onCalculate(lastPeriodDate, cycleLength, periodDuration)
    }
  }

  const handleReset = () => {
    setLastPeriodDate('')
    setCycleLength(28)
    setPeriodDuration(5)
    setErrors({})
  }

  return (
    <section id="calculator" className="section-padding py-16 sm:py-24">
      <div className="max-w-2xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
          className="text-center mb-10"
        >
          <h2 className="text-3xl sm:text-4xl font-bold mb-4">{t.calculator.title}</h2>
          <div className="w-16 h-1 bg-gradient-to-r from-primary-500 to-accent-500 rounded-full mx-auto" />
        </motion.div>

        <Card>
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Date Picker */}
            <div>
              <label className="block text-sm font-medium text-[var(--color-text-secondary)] mb-2">
                {t.calculator.lastPeriod}
              </label>
              <div className="relative">
                <CalendarIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-[var(--color-text-muted)]" />
                <DatePicker
                  value={lastPeriodDate}
                  onChange={(val) => setLastPeriodDate(val)}
                  placeholder={isRTL ? 'يوم/شهر/سنة' : 'DD/MM/YYYY'}
                  className="pl-10"
                  isRTL={isRTL}
                />
              </div>
              {errors.date && <p className="text-red-500 text-sm mt-1">{errors.date}</p>}
            </div>

            {/* Cycle Length */}
            <div>
              <label className="block text-sm font-medium text-[var(--color-text-secondary)] mb-2">
                {t.calculator.cycleLength} (21-40 {t.calculator.days})
              </label>
              <div className="flex items-center gap-4">
                <input
                  type="range"
                  min="21"
                  max="40"
                  value={cycleLength}
                  onChange={(e) => setCycleLength(parseInt(e.target.value))}
                  className="flex-1 accent-primary-500"
                />
                <span className="w-16 text-center font-bold text-primary-600 bg-primary-50 dark:bg-primary-900/20 py-2 rounded-lg">
                  {cycleLength}
                </span>
              </div>
              {errors.cycleLength && <p className="text-red-500 text-sm mt-1">{errors.cycleLength}</p>}
            </div>

            {/* Period Duration */}
            <div>
              <label className="block text-sm font-medium text-[var(--color-text-secondary)] mb-2">
                {t.calculator.periodDuration} (2-10 {t.calculator.days})
              </label>
              <div className="flex items-center gap-4">
                <input
                  type="range"
                  min="2"
                  max="10"
                  value={periodDuration}
                  onChange={(e) => setPeriodDuration(parseInt(e.target.value))}
                  className="flex-1 accent-primary-500"
                />
                <span className="w-16 text-center font-bold text-primary-600 bg-primary-50 dark:bg-primary-900/20 py-2 rounded-lg">
                  {periodDuration}
                </span>
              </div>
              {errors.periodDuration && <p className="text-red-500 text-sm mt-1">{errors.periodDuration}</p>}
            </div>

            {/* Buttons */}
            <div className="flex flex-col sm:flex-row gap-3 pt-4">
              <Button type="submit" variant="primary" icon={Calculator} className="flex-1">
                {t.calculator.calculate}
              </Button>
              <Button type="button" variant="secondary" icon={RotateCcw} onClick={handleReset} className="flex-1">
                {t.calculator.reset}
              </Button>
            </div>
          </form>
        </Card>
      </div>
    </section>
  )
}
