import { addDays, subDays, differenceInDays, startOfMonth, endOfMonth, eachDayOfInterval, isSameDay, isToday } from 'date-fns'

export function calculateCycle(lastPeriodDate, cycleLength, periodDuration) {
  const startDate = new Date(lastPeriodDate)
  const cycleLengthNum = parseInt(cycleLength)
  const periodDurationNum = parseInt(periodDuration)

  // Next period
  const nextPeriodStart = addDays(startDate, cycleLengthNum)
  const nextPeriodEnd = addDays(nextPeriodStart, periodDurationNum - 1)

  // Ovulation (14 days before next period)
  const ovulationDate = subDays(nextPeriodStart, 14)

  // Fertile window (5 days before ovulation + ovulation day)
  const fertileStart = subDays(ovulationDate, 5)
  const fertileEnd = ovulationDate

  // Days remaining
  const today = new Date()
  const daysRemaining = Math.max(0, differenceInDays(nextPeriodStart, today))

  // Current phase
  const daysSinceLastPeriod = differenceInDays(today, startDate)
  let currentPhase = 'menstruation'
  if (daysSinceLastPeriod >= periodDurationNum && daysSinceLastPeriod < cycleLengthNum - 14) {
    currentPhase = 'follicular'
  } else if (daysSinceLastPeriod >= cycleLengthNum - 14 && daysSinceLastPeriod <= cycleLengthNum - 14 + 2) {
    currentPhase = 'ovulation'
  } else if (daysSinceLastPeriod > cycleLengthNum - 14 + 2) {
    currentPhase = 'luteal'
  }

  // Next 3 cycles
  const nextCycles = []
  let cycleStart = nextPeriodStart
  for (let i = 0; i < 3; i++) {
    const periodStart = cycleStart
    const periodEnd = addDays(periodStart, periodDurationNum - 1)
    const ovulation = subDays(addDays(periodStart, cycleLengthNum), 14)
    nextCycles.push({
      periodStart,
      periodEnd,
      ovulation,
    })
    cycleStart = addDays(periodStart, cycleLengthNum)
  }

  return {
    nextPeriodStart,
    nextPeriodEnd,
    ovulationDate,
    fertileStart,
    fertileEnd,
    daysRemaining,
    currentPhase,
    nextCycles,
    cycleLength: cycleLengthNum,
    periodDuration: periodDurationNum,
    lastPeriodDate: startDate,
  }
}

export function getCalendarDays(cycleData, monthDate) {
  const start = startOfMonth(monthDate)
  const end = endOfMonth(monthDate)
  const days = eachDayOfInterval({ start, end })

  return days.map(day => {
    let type = 'normal'
    if (isSameDay(day, cycleData.ovulationDate)) {
      type = 'ovulation'
    } else if (day >= cycleData.fertileStart && day <= cycleData.fertileEnd) {
      type = 'fertile'
    } else if (day >= cycleData.lastPeriodDate && day <= addDays(cycleData.lastPeriodDate, cycleData.periodDuration - 1)) {
      type = 'period'
    } else if (day >= cycleData.nextPeriodStart && day <= cycleData.nextPeriodEnd) {
      type = 'period'
    }

    return {
      date: day,
      type,
      isToday: isToday(day),
    }
  })
}

// Arabic month names
const arabicMonths = [
  'يناير', 'فبراير', 'مارس', 'إبريل', 'مايو', 'يونيو',
  'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
]

function pad(number) {
  return String(number).padStart(2, '0')
}

function getArabicMonthNameText(monthIndex) {
  const arabicMonths = [
    'يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو',
    'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
  ]
  return arabicMonths[monthIndex]
}

function getEnglishMonthName(monthIndex) {
  const englishMonths = [
    'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'
  ]
  return englishMonths[monthIndex]
}

export function formatDateShort(date, language = 'en') {
  const d = new Date(date)
  if (language === 'ar') {
    return `${d.getDate()} ${getArabicMonthNameText(d.getMonth())} ${d.getFullYear()}`
  }
  return `${d.getDate()} ${getEnglishMonthName(d.getMonth())} ${d.getFullYear()}`
}

export function formatDateFull(date, language = 'en') {
  const d = new Date(date)
  if (language === 'ar') {
    return `${d.getDate()} ${getArabicMonthNameText(d.getMonth())} ${d.getFullYear()}`
  }
  return `${d.getDate()} ${getEnglishMonthName(d.getMonth())} ${d.getFullYear()}`
}

export function formatDateRange(start, end, language = 'en') {
  const startDate = new Date(start)
  const endDate = new Date(end)
  if (language === 'ar') {
    return `${pad(startDate.getDate())} ${getArabicMonthNameText(startDate.getMonth())} ${startDate.getFullYear()} - ${pad(endDate.getDate())} ${getArabicMonthNameText(endDate.getMonth())} ${endDate.getFullYear()}`
  }
  return `${startDate.getDate()} ${getEnglishMonthName(startDate.getMonth())} ${startDate.getFullYear()} - ${endDate.getDate()} ${getEnglishMonthName(endDate.getMonth())} ${endDate.getFullYear()}`
}

export function getArabicMonthName(monthIndex) {
  return arabicMonths[monthIndex]
}

export function getArabicWeekDays() {
  return ['السبت', 'الأحد', 'الإثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة']
}
