import { useState, useRef, useEffect } from 'react'
import { format, addMonths, subMonths, startOfMonth, endOfMonth, eachDayOfInterval, isSameDay } from 'date-fns'

export function DatePicker({ value, onChange, placeholder = 'DD/MM/YYYY', className = '', isRTL = false }) {
  const [open, setOpen] = useState(false)
  const [viewMonth, setViewMonth] = useState(value ? new Date(value) : new Date())
  const ref = useRef(null)

  useEffect(() => {
    const handleClick = (e) => {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false)
    }
    document.addEventListener('mousedown', handleClick)
    return () => document.removeEventListener('mousedown', handleClick)
  }, [])

  useEffect(() => {
    if (value) setViewMonth(new Date(value))
  }, [value])

  const display = value ? format(new Date(value), 'dd/MM/yyyy') : ''

  const start = startOfMonth(viewMonth)
  const end = endOfMonth(viewMonth)
  const days = eachDayOfInterval({ start, end })

  const selectDate = (d) => {
    // emit ISO yyyy-MM-dd so rest of app can parse
    const iso = format(d, 'yyyy-MM-dd')
    onChange && onChange(iso)
    setOpen(false)
  }

  return (
    <div className={`relative inline-block text-left w-full ${className}`} ref={ref}>
      <div className="relative">
        <input
          type="text"
          readOnly
          dir="ltr"
          value={display}
          placeholder={placeholder}
          onClick={() => setOpen(!open)}
          className="input-field pl-10 cursor-pointer"
        />
        <button type="button" onClick={() => setOpen(!open)} className="absolute right-3 top-1/2 -translate-y-1/2 p-1.5 rounded-md hover:bg-[var(--color-surface)]">
          <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5 text-[var(--color-text-muted)]" viewBox="0 0 24 24" fill="none" stroke="currentColor"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><path d="M16 2v4M8 2v4M3 10h18"/></svg>
        </button>
      </div>

      {open && (
        <div className="absolute mt-2 right-0 z-50 w-72 bg-[var(--color-surface-elevated)] border border-[var(--color-border)] rounded-lg shadow-lg p-3">
          <div className="flex items-center justify-between mb-2">
            <button onClick={() => setViewMonth(subMonths(viewMonth, 1))} className="p-1 rounded hover:bg-[var(--color-surface)]">‹</button>
            <div className="font-medium">{format(viewMonth, 'MMMM yyyy')}</div>
            <button onClick={() => setViewMonth(addMonths(viewMonth, 1))} className="p-1 rounded hover:bg-[var(--color-surface)]">›</button>
          </div>

          <div className="grid grid-cols-7 gap-1 text-xs text-[var(--color-text-muted)] mb-1">
            <div className="text-center">Su</div>
            <div className="text-center">Mo</div>
            <div className="text-center">Tu</div>
            <div className="text-center">We</div>
            <div className="text-center">Th</div>
            <div className="text-center">Fr</div>
            <div className="text-center">Sa</div>
          </div>

          <div className="grid grid-cols-7 gap-1">
            {Array.from({ length: start.getDay() }).map((_, i) => (
              <div key={`empty-${i}`} />
            ))}

            {days.map((d) => (
              <button
                key={d.toISOString()}
                type="button"
                onClick={() => selectDate(d)}
                className={`w-8 h-8 flex items-center justify-center rounded ${isSameDay(d, new Date(value || '')) ? 'bg-primary-100 text-primary-600' : 'hover:bg-[var(--color-surface)]'}`}
              >
                {d.getDate()}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

export default DatePicker
