import { motion } from 'framer-motion'
import { HelpCircle } from 'lucide-react'
import { useAppContext } from '../../context/AppContext'
import { Accordion } from '../UI/Accordion'

export function FAQ() {
  const { t } = useAppContext()

  const faqItems = t.faq.questions.map((q) => ({
    question: q.q,
    answer: q.a,
  }))

  return (
    <section className="section-padding py-12">
      <div className="max-w-3xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
          className="text-center mb-10"
        >
          <div className="inline-flex items-center justify-center w-14 h-14 mb-4 rounded-2xl bg-gradient-to-br from-primary-400 to-primary-600 shadow-lg">
            <HelpCircle className="w-7 h-7 text-white" />
          </div>
          <h2 className="text-3xl sm:text-4xl font-bold mb-4">{t.faq.title}</h2>
          <div className="w-16 h-1 bg-gradient-to-r from-primary-500 to-accent-500 rounded-full mx-auto" />
        </motion.div>

        <Accordion items={faqItems} />
      </div>
    </section>
  )
}
