import { useState } from 'react'
import { motion } from 'framer-motion'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import { useAppContext } from '../../context/AppContext'
import { Card } from '../UI/Card'
import { getCalendarDays, getArabicMonthName, getArabicWeekDays, formatDateFull } from '../../utils/cycleCalculations'
import { addMonths, subMonths } from 'date-fns'

export function CalendarView({ cycleData }) {
  const { t, isRTL } = useAppContext()
  const [currentMonth, setCurrentMonth] = useState(new Date())

  const days = getCalendarDays(cycleData, currentMonth)
  const weekDays = isRTL ? getArabicWeekDays() : ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
  const monthName = isRTL
    ? formatDateFull(currentMonth, 'ar').replace(/^\d+\s/, '')
    : formatDateFull(currentMonth, 'en').replace(/^\d+\s/, '')

  const getDayStyle = (type) => {
    switch (type) {
      case 'period': return 'bg-red-500 text-white'
      case 'ovulation': return 'bg-primary-500 text-white'
      case 'fertile': return 'bg-emerald-400 text-white'
      default: return 'hover:bg-[var(--color-surface)]'
    }
  }

  return (
    <section id="calendar" className="section-padding py-12">
      <div className="max-w-4xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
          className="text-center mb-10"
        >
          <h2 className="text-3xl sm:text-4xl font-bold mb-4">{t.calendar.title}</h2>
          <div className="w-16 h-1 bg-gradient-to-r from-primary-500 to-accent-500 rounded-full mx-auto" />
        </motion.div>

        <Card className="p-4 sm:p-6">
          <div className="flex items-center justify-between mb-6">
            <button
              onClick={() => setCurrentMonth(subMonths(currentMonth, 1))}
              className="p-2 rounded-lg hover:bg-[var(--color-surface)] transition-colors"
            >
              {isRTL ? <ChevronRight className="w-5 h-5" /> : <ChevronLeft className="w-5 h-5" />}
            </button>
            <h3 className="text-lg font-bold">{monthName}</h3>
            <button
              onClick={() => setCurrentMonth(addMonths(currentMonth, 1))}
              className="p-2 rounded-lg hover:bg-[var(--color-surface)] transition-colors"
            >
              {isRTL ? <ChevronLeft className="w-5 h-5" /> : <ChevronRight className="w-5 h-5" />}
            </button>
          </div>

          <div className="grid grid-cols-7 gap-1 mb-2">
            {weekDays.map((day) => (
              <div key={day} className="text-center text-xs sm:text-sm font-medium text-[var(--color-text-muted)] py-2">
                {day}
              </div>
            ))}
          </div>

          <div className="grid grid-cols-7 gap-1">
            {days.map((day, index) => (
              <motion.div
                key={index}
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ delay: index * 0.01 }}
                className={`
                  aspect-square flex items-center justify-center rounded-lg text-sm font-medium
                  ${getDayStyle(day.type)}
                  ${day.isToday ? 'ring-2 ring-primary-500 ring-offset-2 dark:ring-offset-[var(--color-surface-elevated)]' : ''}
                `}
              >
                {day.date.getDate()}
              </motion.div>
            ))}
          </div>

          <div className="flex flex-wrap gap-4 mt-6 pt-4 border-t border-[var(--color-border)]">
            <div className="flex items-center gap-2">
              <div className="w-4 h-4 rounded bg-red-500" />
              <span className="text-sm text-[var(--color-text-secondary)]">{t.calendar.period}</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-4 h-4 rounded bg-primary-500" />
              <span className="text-sm text-[var(--color-text-secondary)]">{t.calendar.ovulation}</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-4 h-4 rounded bg-emerald-400" />
              <span className="text-sm text-[var(--color-text-secondary)]">{t.calendar.fertile}</span>
            </div>
          </div>
        </Card>
      </div>
    </section>
  )
}
