import { motion } from 'framer-motion'
import { Droplets, Sun, Egg, Moon, Check } from 'lucide-react'
import { useAppContext } from '../../context/AppContext'
import { Card } from '../UI/Card'

const phaseIcons = {
  menstruation: Droplets,
  follicular: Sun,
  ovulation: Egg,
  luteal: Moon,
}

const phaseColors = {
  menstruation: 'from-red-400 to-red-600',
  follicular: 'from-amber-400 to-amber-600',
  ovulation: 'from-primary-400 to-primary-600',
  luteal: 'from-indigo-400 to-indigo-600',
}

export function HealthTips({ currentPhase = 'menstruation' }) {
  const { t } = useAppContext()
  const phase = t.healthTips[currentPhase] || t.healthTips.menstruation
  const Icon = phaseIcons[currentPhase] || Droplets
  const gradient = phaseColors[currentPhase] || 'from-red-400 to-red-600'

  return (
    <section className="section-padding py-12">
      <div className="max-w-4xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
          className="text-center mb-10"
        >
          <h2 className="text-3xl sm:text-4xl font-bold mb-4">{t.healthTips.title}</h2>
          <div className="w-16 h-1 bg-gradient-to-r from-primary-500 to-accent-500 rounded-full mx-auto" />
        </motion.div>

        <Card className="p-6 sm:p-8 overflow-hidden">
          <div className="flex items-center gap-4 mb-6">
            <div className={`w-14 h-14 rounded-2xl bg-gradient-to-br ${gradient} flex items-center justify-center shadow-lg`}>
              <Icon className="w-7 h-7 text-white" />
            </div>
            <div>
              <h3 className="text-xl font-bold">{phase.title}</h3>
              <p className="text-sm text-[var(--color-text-muted)]">
                Personalized tips for your current phase
              </p>
            </div>
          </div>

          <div className="space-y-3">
            {phase.tips.map((tip, index) => (
              <motion.div
                key={index}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: index * 0.1 }}
                className="flex items-start gap-3 p-4 rounded-xl bg-[var(--color-surface)] border border-[var(--color-border)] hover:border-primary-200 dark:hover:border-primary-800 transition-colors"
              >
                <div className={`w-6 h-6 rounded-full bg-gradient-to-br ${gradient} flex items-center justify-center shrink-0 mt-0.5`}>
                  <Check className="w-3.5 h-3.5 text-white" />
                </div>
                <p className="text-[var(--color-text-secondary)] leading-relaxed">{tip}</p>
              </motion.div>
            ))}
          </div>
        </Card>
      </div>
    </section>
  )
}
