import { createContext, useContext, useState, useCallback } from 'react'
import { translations } from '../data/translations'
import { useTheme } from '../hooks/useTheme'
import { useLanguage } from '../hooks/useLanguage'
import { useNotifications } from '../hooks/useNotifications'
import { getHistory, deleteHistoryItem as deleteItem, updateHistoryItem as updateItem, clearAllHistory as clearAll } from '../utils/localStorage'

const AppContext = createContext(null)

export function AppProvider({ children }) {
  const { theme, setTheme } = useTheme()
  const { language, setLanguage } = useLanguage()
  const { permissionStatus, notificationSettings, enableNotifications, updateSettings } = useNotifications()
  const [showSettings, setShowSettings] = useState(false)
  const [history, setHistory] = useState(() => getHistory())

  const t = translations[language] || translations.en
  const isRTL = language === 'ar'

  const deleteHistoryItem = useCallback((id) => {
    deleteItem(id)
    setHistory(getHistory())
  }, [])

  const updateHistoryItem = useCallback((id, updates) => {
    updateItem(id, updates)
    setHistory(getHistory())
  }, [])

  const clearAllHistory = useCallback(() => {
    clearAll()
    setHistory([])
  }, [])

  const value = {
    t,
    theme,
    setTheme,
    language,
    setLanguage,
    isRTL,
    showSettings,
    setShowSettings,
    history,
    deleteHistoryItem,
    updateHistoryItem,
    clearAllHistory,
    permissionStatus,
    notificationSettings,
    enableNotifications,
    updateSettings,
  }

  return (
    <AppContext.Provider value={value}>
      {children}
    </AppContext.Provider>
  )
}

export function useAppContext() {
  const context = useContext(AppContext)
  if (!context) {
    throw new Error('useAppContext must be used within AppProvider')
  }
  return context
}
