import { useState } from 'react'
import { motion } from 'framer-motion'
import { Bell, BellRing, Clock, Calendar } from 'lucide-react'
import { useAppContext } from '../../context/AppContext'
import { Card } from '../UI/Card'
import { Button } from '../UI/Button'
import { Toggle } from '../UI/Toggle'

export function NotificationsView() {
  const { t, permissionStatus, enableNotifications } = useAppContext()
  const [localSettings, setLocalSettings] = useState({
    enabled: false,
    periodDays: 2,
    ovulationDays: 1,
    time: '08:00',
  })

  const handleEnable = async () => {
    const granted = await enableNotifications()
    if (granted) {
      setLocalSettings({ ...localSettings, enabled: true })
    }
  }

  return (
    <section className="section-padding py-12 no-print">
      <div className="max-w-2xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
          className="text-center mb-10"
        >
          <div className="inline-flex items-center justify-center w-14 h-14 mb-4 rounded-2xl bg-gradient-to-br from-primary-400 to-primary-600 shadow-lg">
            <Bell className="w-7 h-7 text-white" />
          </div>
          <h2 className="text-3xl sm:text-4xl font-bold mb-4">{t.notifications.title}</h2>
          <div className="w-16 h-1 bg-gradient-to-r from-primary-500 to-accent-500 rounded-full mx-auto" />
        </motion.div>

        <Card className="p-6 sm:p-8 space-y-6">
          {permissionStatus !== 'granted' && (
            <div className="p-4 bg-amber-50 dark:bg-amber-900/20 rounded-xl flex items-start gap-3">
              <BellRing className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />
              <div>
                <p className="font-medium text-amber-800 dark:text-amber-200 mb-1">
                  {t.notifications.enable}
                </p>
                <Button variant="primary" size="sm" onClick={handleEnable}>
                  Enable Notifications
                </Button>
              </div>
            </div>
          )}

          <div className="space-y-6" style={{ opacity: permissionStatus === 'granted' ? 1 : 0.5, pointerEvents: permissionStatus === 'granted' ? 'auto' : 'none' }}>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <Calendar className="w-5 h-5 text-primary-500" />
                <div>
                  <p className="font-medium">{t.notifications.periodReminder}</p>
                </div>
              </div>
              <Toggle
                checked={localSettings.enabled}
                onChange={(checked) => setLocalSettings({ ...localSettings, enabled: checked })}
                disabled={permissionStatus !== 'granted'}
              />
            </div>

            <div className="flex items-center gap-3">
              <Clock className="w-5 h-5 text-accent-500" />
              <div className="flex-1">
                <p className="font-medium mb-2">{t.notifications.time}</p>
                <input
                  type="time"
                  value={localSettings.time}
                  onChange={(e) => setLocalSettings({ ...localSettings, time: e.target.value })}
                  className="input-field w-auto"
                  disabled={permissionStatus !== 'granted'}
                />
              </div>
            </div>
          </div>
        </Card>
      </div>
    </section>
  )
}
