import { useState, useCallback } from 'react'
import { AppProvider, useAppContext } from './context/AppContext'
import { Navigation } from './components/Navigation/Navigation'
import { Hero } from './components/Hero/Hero'
import { CalculatorForm } from './components/CalculatorForm/CalculatorForm'
import { ResultCards } from './components/ResultCards/ResultCards'
import { CalendarView } from './components/CalendarView/CalendarView'
import { HealthTips } from './components/HealthTips/HealthTips'
import { FAQ } from './components/FAQ/FAQ'
import { Footer } from './components/Footer/Footer'
import { HistoryView } from './components/History/History'
import { ExportView } from './components/Export/Export'
import { NotificationsView } from './components/Notifications/Notifications'
import { SettingsModal } from './components/Settings/SettingsModal'
import { calculateCycle } from './utils/cycleCalculations'

const AppContent = () => {
  const [results, setResults] = useState(null)
  const [cycleData, setCycleData] = useState(null)

  const handleCalculate = useCallback((lastPeriodDate, cycleLength, periodDuration) => {
    const calcResults = calculateCycle(lastPeriodDate, cycleLength, periodDuration)
    if (calcResults) {
      setResults(calcResults)
      setCycleData(calcResults)
      setTimeout(() => {
        const element = document.getElementById('results')
        if (element) element.scrollIntoView({ behavior: 'smooth' })
      }, 100)
    }
  }, [])

  return (
    <div className="min-h-screen bg-[var(--color-bg)]">
      <Navigation />
      <SettingsModal />

      <main>
        <Hero />
        <CalculatorForm onCalculate={handleCalculate} />

        {results && (
          <div id="results">
            <ResultCards results={results} />
            <CalendarView cycleData={cycleData} />
            <HealthTips currentPhase={results.currentPhase} />
            <ExportView results={results} />
          </div>
        )}

        <HistoryView />
        <NotificationsView />
        <FAQ />
      </main>

      <Footer />
    </div>
  )
}

function App() {
  return (
    <AppProvider>
      <AppContent />
    </AppProvider>
  )
}

export default App
